package com.villageclock.app;

import android.app.*;
import android.content.*;
import android.view.*;
import android.widget.*;
import org.junit.*;
import org.junit.runner.RunWith;
import org.robolectric.*;
import org.robolectric.annotation.Config;
import org.robolectric.shadows.ShadowAlertDialog;
import java.time.Instant;
import java.util.*;
import static org.junit.Assert.*;
import static org.robolectric.Shadows.shadowOf;

@RunWith(RobolectricTestRunner.class) @Config(sdk={26,29,35})
public class FinishClocksTest {
    private Context context;private TimeZone oldZone;private long now;
    @Before public void setup(){context=RuntimeEnvironment.getApplication();Store.prefs(context).edit().clear().commit();oldZone=TimeZone.getDefault();TimeZone.setDefault(TimeZone.getTimeZone("Asia/Manila"));now=System.currentTimeMillis()/1000*1000;}
    @After public void restore(){TimeZone.setDefault(oldZone);}
    private long at(String instant){return Instant.parse(instant).toEpochMilli();}
    private Village parse(String fields)throws Exception{return ExportParser.parse("{\"tag\":\"#CLOCK1\",\"timestamp\":"+now/1000+",\"buildings\":[],"+fields+"}",Store.catalog(context),now);}
    private void mode(String mode){Store.prefs(context).edit().putString(ClockText.PREF,mode).commit();}
    @Test public void clockFormatsRespectLocalZoneAndExplicit12Or24Hours(){long start=at("2026-11-08T04:00:00Z"),end=at("2026-11-08T05:15:00Z");mode("12");assertEquals("1:15 PM",ClockText.at(context,end,start));mode("24");assertEquals("13:15",ClockText.at(context,end,start));assertEquals("",ClockText.at(context,0,start));}
    @Test public void midnightNoonAndFutureDaysStayUnambiguous(){long start=at("2026-11-08T04:00:00Z");mode("12");assertEquals("12:01 PM",ClockText.at(context,at("2026-11-08T04:01:00Z"),start));assertEquals("Tomorrow\n12:01 AM",ClockText.at(context,at("2026-11-08T16:01:00Z"),start));assertTrue(ClockText.at(context,at("2026-11-10T05:15:00Z"),start).startsWith("Nov 10\n"));}
    @Test public void deviceDefaultAndDstUseActualFinishInstant(){mode("device");android.provider.Settings.System.putString(context.getContentResolver(),android.provider.Settings.System.TIME_12_24,"24");assertEquals("13:15",ClockText.at(context,at("2026-11-08T05:15:00Z"),at("2026-11-08T04:00:00Z")));mode("24");TimeZone.setDefault(TimeZone.getTimeZone("America/New_York"));assertEquals("01:30",ClockText.at(context,at("2026-11-01T05:30:00Z"),at("2026-11-01T04:00:00Z")));assertEquals("01:30",ClockText.at(context,at("2026-11-01T06:30:00Z"),at("2026-11-01T04:00:00Z")));}
    @Test public void effectsAreDeduplicatedAndExistWithoutRunningJobs()throws Exception{Village village=parse("\"boosts\":{\"builder_boost\":1800,\"builder_consumable\":562,\"lab_boost\":7140,\"lab_consumable\":600},\"units\":[{\"data\":4000000,\"timer\":200000},{\"data\":4000001,\"timer\":300000}]");assertEquals(4,ActiveEffects.active(village,now).size());assertEquals(27,village.upgrades.get(0).timing.speed(0));assertEquals("Builder Bite",ActiveEffects.active(village,now).get(0).name);assertEquals(3,ActiveEffects.active(village,now+563000).size());Village idle=parse("\"boosts\":{\"builder_boost\":1800}");assertTrue(idle.upgrades.isEmpty());assertEquals(1,ActiveEffects.active(idle,now).size());assertEquals(now+1800000,ActiveEffects.active(idle,now).get(0).endsAt);}
    @Test public void regularBuilderAvailabilityExcludesGoblinAndOtherQueues()throws Exception{String raw="{\"tag\":\"#BUSY1\",\"timestamp\":"+now/1000+",\"buildings\":[{\"data\":1000015,\"cnt\":2},{\"data\":1000008,\"timer\":3600},{\"data\":1000009,\"timer\":1800},{\"data\":1000011,\"timer\":60,\"extra\":true}],\"units\":[{\"data\":4000000,\"timer\":120}]}";Village village=ExportParser.parse(raw,Store.catalog(context),now);assertEquals(now+1800000,village.nextFree(Village.Queue.BUILDERS,now));assertEquals(now+120000,village.nextFree(Village.Queue.LAB,now));assertEquals(0,village.nextFree(Village.Queue.BUILDERS,now+1800001));assertEquals(0,village.nextFree(Village.Queue.BASE,now));View panel=TimerPanels.nextFree(context,village,Village.Queue.BUILDERS,now);assertTrue(text(panel).contains("Next free in"));assertTrue(text(panel).contains(ClockText.at(context,now+1800000,now)));}
    @Test public void widgetScrollListHasOneBoostGroupAndNoRepeatedPotionLabels()throws Exception{Village village=parse("\"boosts\":{\"lab_boost\":3600},\"units\":[{\"data\":4000000,\"timer\":172800},{\"data\":4000001,\"timer\":200000}]");List<Object> items=VillageWidget.displayItems(village,now);assertEquals(3,items.size());assertTrue(items.get(0) instanceof ActiveEffects.Effect);assertEquals(VillageWidget.itemId(items.get(0)),VillageWidget.itemId(VillageWidget.displayItems(village,now+1000).get(0)));View effect=VillageWidget.styledItem(context,village,items,0,now,true).apply(context,new FrameLayout(context));assertTrue(text(effect).contains("Research Potion 24×"));assertTrue(text(effect).contains("Ends at"));View upgrade=VillageWidget.styledItem(context,village,items,1,now,true).apply(context,new FrameLayout(context));assertEquals(View.GONE,upgrade.findViewById(R.id.row_boost).getVisibility());assertTrue(((TextView)upgrade.findViewById(R.id.row_finish_at)).getText().toString().startsWith("Finishes at"));assertEquals(2,VillageWidget.displayItems(village,now+3600000).size());}
    @Test public void boostsStayAccountBoundWithGlobalClockPreference()throws Exception{Village a=parse("\"boosts\":{\"builder_boost\":1800}");String raw="{\"tag\":\"#OTHER1\",\"timestamp\":"+now/1000+",\"buildings\":[],\"boosts\":{\"lab_boost\":3600}}";Village b=ExportParser.parse(raw,Store.catalog(context),now);assertEquals("Builder Potion",ActiveEffects.active(a,now).get(0).name);assertEquals("Research Potion",ActiveEffects.active(b,now).get(0).name);mode("24");assertEquals(1,VillageWidget.displayItems(a,now).size());assertEquals(1,VillageWidget.displayItems(b,now).size());assertFalse(ClockText.at(context,now+1800000,now).contains("M"));}
    @Test public void expiryAlarmRefreshesBoostEvenWhenUpgradeFinishesLater()throws Exception{String raw="{\"tag\":\"#ALARM1\",\"timestamp\":"+now/1000+",\"buildings\":[],\"boosts\":{\"lab_boost\":60},\"units\":[{\"data\":4000000,\"timer\":172800}]}";Village village=ExportParser.parse(raw,Store.catalog(context),now);Store.save(context,raw,village);Reminders.schedule(context);assertEquals(now+60000,shadowOf(context.getSystemService(AlarmManager.class)).peekNextScheduledAlarm().triggerAtTime);}
    @Test public void eventDeadlineIsOfficialAndDoesNotApplyAnotherSpeedMultiplier()throws Exception{Village village=new Village("#EVENT1",now,12,6,2,Collections.emptyList());long eventNow=at("2026-11-08T00:00:00Z");ActiveEffects.Effect event=ActiveEffects.active(village,eventNow).get(0);assertTrue(event.event);assertEquals("50% off",event.rate);assertEquals(at("2026-11-16T08:00:00Z"),event.endsAt);assertTrue(ActiveEffects.active(village,event.endsAt).isEmpty());assertTrue(ActiveEffects.active(new Village("#LOW1",now,2,1,0,Collections.emptyList()),eventNow).isEmpty());}
    @Test public void settingsExposeBothFormatsAndApplyWithoutChangingAccount(){MainActivity activity=Robolectric.buildActivity(MainActivity.class).setup().get();activity.findViewById(R.id.settings_toggle).performClick();activity.findViewById(R.id.time_format_setting).performClick();AlertDialog dialog=ShadowAlertDialog.getLatestAlertDialog();dialog.getListView().performItemClick(dialog.getListView().getAdapter().getView(2,null,dialog.getListView()),2,2);shadowOf(android.os.Looper.getMainLooper()).idle();assertEquals("24",ClockText.mode(activity));assertTrue(((Button)activity.findViewById(R.id.time_format_setting)).getText().toString().contains("24-Hour"));}
    @Test public void widgetServiceTracksIdlePotionAndStopsAfterItsExpiry()throws Exception{
        String raw="{\"tag\":\"#POTION1\",\"timestamp\":"+now/1000+",\"buildings\":[],\"boosts\":{\"builder_boost\":1800}}";Village village=ExportParser.parse(raw,Store.catalog(context),now);Store.save(context,raw,village);android.appwidget.AppWidgetManager manager=android.appwidget.AppWidgetManager.getInstance(context);int id=shadowOf(manager).createWidget(VillageWidget.class,R.layout.widget);Store.bind(context,id,village.tag);LiveTimerService.cache(id,village.tag,village);assertTrue(LiveTimerService.wanted(context));
        String old=raw.replace("\"timestamp\":"+now/1000,"\"timestamp\":"+(now/1000-2000));LiveTimerService.cache(id,village.tag,ExportParser.parse(old,Store.catalog(context),now));assertFalse(LiveTimerService.wanted(context));LiveTimerService.forget(id);
    }
    @Test public void nativeEffectTimerAndStackedDeadlineStayConsistent()throws Exception{
        Village village=parse("\"boosts\":{\"builder_boost\":7200}");ActiveEffects.Effect effect=ActiveEffects.active(village,now).get(0);assertEquals(now+7200000,effect.endsAt);View view=VillageWidget.styledItem(context,village,VillageWidget.displayItems(village,now),0,now,false).apply(context,new FrameLayout(context));assertEquals(View.VISIBLE,view.findViewById(R.id.effect_timer).getVisibility());assertEquals(View.GONE,view.findViewById(R.id.effect_remaining).getVisibility());assertNotEquals(R.drawable.ic_clock,ActiveEffects.icon(context,effect));
    }
    private String text(View view){String out=view instanceof TextView?((TextView)view).getText().toString():"";if(view instanceof ViewGroup)for(int n=0;n<((ViewGroup)view).getChildCount();n++)out+=" "+text(((ViewGroup)view).getChildAt(n));return out;}
}
